CONDS = [
    ('breadth_open', '<', 0.5),
    ('dist_pdl_atr', '<=', 0.14),
    ('emaDiff_chg3', '>=', 0.15),
    ('or_low_dist_atr', '>=', 0.41),
]
LAYERS = ['breadth_open < 0.5', 'dist_pdl_atr <= 0.14', 'emaDiff_chg3 >= 0.15', 'or_low_dist_atr >= 0.41', 'window 1300-1500']


def mask(df) -> np.ndarray:
    x = compute(df, names=['dist_pdl_atr', 'emaDiff_chg3', 'or_low_dist_atr'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
